"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type OrbitPrimitiveProps = ComponentProps<typeof motion.div>;

export function OrbitPrimitive({ children, ...props }: OrbitPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {rotate: 0}}
      animate={{rotate: 360}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 6, ease: [0.23, 1, 0.32, 1], repeat: Infinity, repeatType: "loop" }}
      aria-hidden="true"
    >
      {children}
    </motion.div>
  );
}
